"use strict";

module.exports = {
    async up(queryInterface, Sequelize) {
        const { DataTypes } = Sequelize;
        const tables = (await queryInterface.showAllTables()).map(String);

        if (!tables.includes("user_account")) {
            await queryInterface.createTable("user_account", {
                id: { type: DataTypes.UUID, defaultValue: Sequelize.literal("uuid_generate_v4()"), primaryKey: true },
                full_name: { type: DataTypes.STRING(150), allowNull: false },
                email: { type: DataTypes.STRING(255), allowNull: false, unique: true },
                password_hash: { type: DataTypes.STRING(255), allowNull: false },
                role: { type: DataTypes.STRING(20), allowNull: false },
                staff_id: {
                    type: DataTypes.UUID,
                    allowNull: true,
                    unique: true,
                    references: { model: "staff", key: "id" },
                },
                status: { type: DataTypes.STRING(20), allowNull: false, defaultValue: "active" },
                last_login_at: { type: DataTypes.DATE, allowNull: true },
                created_at: { type: DataTypes.DATE, allowNull: false, defaultValue: Sequelize.fn("NOW") },
                updated_at: { type: DataTypes.DATE, allowNull: false, defaultValue: Sequelize.fn("NOW") },
            });

            await queryInterface.addConstraint("user_account", {
                fields: ["role"],
                type: "check",
                where: { role: ["manager", "employee"] },
                name: "user_account_role_check",
            });

            await queryInterface.addConstraint("user_account", {
                fields: ["status"],
                type: "check",
                where: { status: ["active", "disabled"] },
                name: "user_account_status_check",
            });
        }
    },

    async down(queryInterface) {
        const tables = (await queryInterface.showAllTables()).map(String);
        if (tables.includes("user_account")) {
            await queryInterface.dropTable("user_account");
        }
    },
};

